  color: var(--cafe-ink-5);
  font-size: 14px;
}
.cafe-comments > .cafe-c {
  padding: 16px 0;
}
.cafe-comments > .cafe-c + .cafe-c {
  border-top: 1px solid var(--cafe-outline);
}
.cafe-c-head {
  display: flex;
  align-items: center;
  gap: 16px;
}
.cafe-avatar-sm {
  width: 40px;
  height: 40px;
  font-size: 18px;
  letter-spacing: 0.01em;
}
.cafe-c-name {
  color: var(--cafe-ink-8);
  font-size: 13px;
  font-weight: 600;
  line-height: 19.5px;
  letter-spacing: 0.015em;
}
.cafe-c-time {
  color: var(--cafe-ink-5);
  font-size: 12px;
  line-height: 1.15;
}
.cafe-c-body {
  margin: 4px 0 0;
  padding-left: 56px;
  color: #383838;
  font-size: 13px;
  line-height: 1.5;
  letter-spacing: 0.015em;
  overflow-wrap: anywhere;
}
.cafe-c-actions {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-top: 8px;
  padding-left: 56px;
  font-size: 12px;
  line-height: 1.15;
}
.cafe-c-like,
.cafe-c-action,
.cafe-c-view,
.cafe-c-hide {
  padding: 0;
  border: 0;
  background: none;
  color: var(--cafe-ink-5);
  font: inherit;
  cursor: pointer;
}
.cafe-c-like {
  display: flex;
  align-items: center;
  gap: 4px;
}
.cafe-c-like.on {
  color: #e03636;
}
.cafe-ico svg {
  display: block;
  width: 16px;
  height: 16px;
}
.cafe-c-action:hover,
.cafe-c-view:hover,
.cafe-c-hide:hover {
  text-decoration: underline;
}
.cafe-c-replybox {
  margin: 8px 0 0 56px;
}
.cafe-c-replybox-actions {
  display: flex;
  gap: 8px;
  margin-top: 6px;
}
.cafe-btn-ghost {
  background: transparent;
  color: var(--cafe-ink-8);
}
.cafe-btn-ghost:hover {
  background: var(--cafe-surface-2);
}
.cafe-c-view {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 8px 0 0 56px;
  font-size: 12px;
  line-height: 1.15;
}
/* The old page keeps the space of this short line but does not show it. */
.cafe-c-line {
  width: 24px;
  height: 1px;
  background: transparent;
}
.cafe-c-replies {
  display: flex;
  flex-direction: column;
  gap: 12px;
