}

/* ---- Mobile: rail becomes a bottom bar ---- */
@media (max-width: 767px) {
  .cafe-rail,
  .cafe-header,
  .cafe-menu,
  html[data-cafe-sidebar='open'] .cafe-sidebar {
    display: none !important;
  }
  .cafe-mobile-header {
    display: flex !important;
  }
  .cafe-app {
    flex-direction: column !important;
  }
  .cafe-container {
    padding: 24px 16px !important;
  }
  .cafe-scroll {
    padding-bottom: 57px;
  }
  .cafe-bottom-nav {
    position: fixed;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 40;
    display: flex !important;
    height: 57px;
    border-top: 1px solid #e2e2e2;
    background: #fff;
  }
  .cafe-tab {
    position: relative;
    display: flex;
    flex: 1;
    align-items: center;
    justify-content: center;
    padding: 8px 0;
    color: var(--cafe-ink-5);
  }
  .cafe-tab.active {
    color: var(--cafe-ink);
  }
  .cafe-tab .cafe-badge {
    top: 8px !important;
    right: calc(50% - 20px) !important;
  }
  .cafe-container-post {
    padding: 24px 16px 24px !important;
  }
  .cafe-carousel {
    height: 50vh !important;
    min-height: 240px;
  }
  .cafe-profile-head {
    gap: 16px !important;
  }
  .cafe-profile-avatar {
    width: 80px !important;
    height: 80px !important;
  }
  .cafe-profile-avatar .cafe-profile-initial {
    font-size: 32px !important;
    line-height: 1.5 !important;
  }
  .cafe-name-row {
    flex-direction: column !important;
    align-items: flex-start !important;
  }
  .cafe-profile-name {
    max-width: 100%;
    font-size: 20px !important;
    line-height: 1.15 !important;
    letter-spacing: 0.01em !important;
  }
}

