/* ---- Notifications: bells and the panel ---- */
button.cafe-rail-item {
  background: transparent;
}
.cafe-bell:hover {
  background: rgba(0, 0, 0, 0.05) !important;
}
.cafe-bell.active {
  background: var(--cafe-surface-2) !important;
}
/* With the panel open, the bell is the active item and the page's own is not. */
.cafe-np-open .cafe-rail-item.active:not([data-bell]) {
  background: transparent;
  box-shadow: none;
}
.cafe-np {
  position: fixed;
  top: 0;
  bottom: 0;
  left: 50px;
  z-index: 50;
  display: flex;
  flex-direction: column;
  width: 320px;
  max-width: 90vw;
  border-right: 1px solid var(--cafe-outline);
  background: #fff;
  box-shadow: 8px 0 15px -3px rgba(0, 0, 0, 0.1), 4px 0 6px -4px rgba(0, 0, 0, 0.1);
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  line-height: 1.15;
  letter-spacing: 0.02em;
  color: var(--cafe-ink);
  -webkit-font-smoothing: antialiased;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s, visibility 0.15s;
}
.cafe-np,
.cafe-np *,
.cafe-np *::before,
.cafe-np *::after {
  box-sizing: border-box;
}
.cafe-np.open {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
}
.cafe-np-header {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: space-between;
  min-height: 48px;
  padding: 0 16px;
  border-bottom: 1px solid var(--cafe-outline);
}
.cafe-np-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  line-height: 18.4px;
  letter-spacing: 0.015em;
  color: var(--cafe-ink);
}
.cafe-np-header-actions {
  display: flex;
  align-items: center;
  gap: 4px;
}
.cafe-np-icon-btn {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #171717;
  cursor: pointer;
}
.cafe-np-close {
  color: var(--cafe-ink-5);
}
.cafe-np-icon-btn:hover {
  background: var(--cafe-surface-2);
}
.cafe-np-close:hover {
  color: #383838;
}
.cafe-np-icon-btn:disabled {
  opacity: 0.6;
  cursor: default;
}
.cafe-np-icon,
.cafe-np-empty-icon,
.cafe-np-type-icon {
  display: block;
  line-height: 0;
}
/* The icons' own svg has a fixed size inline; these boxes set the real one. */
.cafe-np-icon svg,
.cafe-np-empty-icon svg,
.cafe-np-type-icon svg {
  width: 100% !important;
  height: 100% !important;
}
.cafe-np-icon {
  width: 16px;
  height: 16px;
}
.cafe-np-list {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
}
.cafe-np-row {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 12px;
  cursor: pointer;
}
.cafe-np-row + .cafe-np-row {
  border-top: 1px solid var(--cafe-outline);
}
.cafe-np-row:hover {
  background: #f8f8f8;
}
.cafe-np-avatar-wrap {
