  flex-shrink: 0;
}
.cafe-np-avatar {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  overflow: hidden;
  border-radius: 9999px;
  background: var(--cafe-surface-2);
  color: var(--cafe-ink-5);
  font-size: 14px;
  font-weight: 500;
  text-transform: uppercase;
}
.cafe-np-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.cafe-np-type {
  position: absolute;
  right: -4px;
  bottom: -4px;
