}
.cafe-np-type-icon {
  width: 8px;
  height: 8px;
}
.cafe-np-text {
  flex: 1;
  min-width: 0;
}
.cafe-np-msg {
  margin: 0;
  font-size: 13px;
  line-height: 19.5px;
  letter-spacing: 0.015em;
