}
.cafe-np-actor {
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--cafe-ink);
}
.cafe-np-time {
  margin-top: 2px;
  font-size: 12px;
  color: var(--cafe-ink-5);
}
.cafe-np-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}
.cafe-np-actions.busy .cafe-btn {
  opacity: 0.6;
  cursor: default;
}
.cafe-np-status {
  display: inline-flex;
  align-items: center;
  height: 20px;
  margin-top: 8px;
  padding: 0 6px;
  border-radius: 9999px;
  background: var(--cafe-surface-2);
