  padding: 16px;
}
.cafe-np-skeleton .cafe-skeleton {
  height: 16px;
  border-radius: 6px;
  background: linear-gradient(90deg, #f3f3f3, #fafafa, #f3f3f3);
  background-size: 200% 100%;
  animation: cafe-pulse 1.2s ease-in-out infinite;
}

/* ---- Code blocks of a post (code.js) ---- */
.cafe-prose .cafe-code-block {
  position: relative;
  margin: 16px 0;
}
.cafe-prose pre.cafe-code {
  display: flex;
  align-items: flex-start;
  gap: 20px;
  margin: 0;
  padding: 12px 16px 12px 12px;
  overflow: hidden;
  border: 1px solid var(--cafe-outline-2, #e2e2e2);
  border-radius: 12px;
  background: #f6f8fa;
  color: #24292e;
  font-family: ui-monospace, Menlo, Monaco, 'Cascadia Mono', 'Segoe UI Mono', 'Roboto Mono', 'Oxygen Mono', 'Ubuntu Mono',
    'Source Code Pro', 'Fira Mono', 'Droid Sans Mono', 'Consolas', 'Courier New', monospace;
  font-size: 12px;
  font-weight: 400;
  line-height: 1.7;
}
.cafe-code-gutter {
  display: flex;
  flex: none;
  flex-direction: column;
  align-items: flex-end;
  color: #999;
  user-select: none;
}
.cafe-code-gutter span {
  display: block;
}
.cafe-prose pre.cafe-code .cafe-code-body {
  flex: 1;
  min-width: 0;
  overflow-x: auto;
  padding: 0;
  background: none;
  font-size: inherit;
  line-height: 1.7;
  white-space: pre;
}
.cafe-code-tools {
  position: absolute;
  top: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 6px 8px 0 0;
  opacity: 0;
  transition: opacity 0.15s;
}
.cafe-code-block:hover .cafe-code-tools,
.cafe-code-tools:focus-within {
  opacity: 1;
}
@media (hover: none) {
  .cafe-code-tools {
    opacity: 1;
  }
}
.cafe-code-language {
  padding: 0 4px;
  color: #999;
  font-size: 12px;
  letter-spacing: 0.02em;
  user-select: none;
}
.cafe-code-copy {
  display: grid;
  place-items: center;
  width: 24px;
  height: 24px;
  padding: 0;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: var(--cafe-ink-8);
  cursor: pointer;
}
.cafe-code-copy:hover {
  background: rgba(0, 0, 0, 0.06);
}
.cafe-code-icon {
  display: block;
  width: 16px;
  height: 16px;
  line-height: 0;
}
.cafe-code-icon svg {
  width: 100% !important;
  height: 100% !important;
}
/* highlight.js, GitHub light: the same colours as the editor's. */
.cafe-code .hljs-doctag,
.cafe-code .hljs-keyword,
.cafe-code .hljs-meta .hljs-keyword,
.cafe-code .hljs-template-tag,
.cafe-code .hljs-template-variable,
.cafe-code .hljs-type,
.cafe-code .hljs-variable.language_ {
  color: #d73a49;
}
.cafe-code .hljs-title,
.cafe-code .hljs-title.class_,
.cafe-code .hljs-title.class_.inherited__,
.cafe-code .hljs-title.function_ {
  color: #6f42c1;
}
.cafe-code .hljs-attr,
.cafe-code .hljs-attribute,
.cafe-code .hljs-literal,
.cafe-code .hljs-meta,
.cafe-code .hljs-number,
.cafe-code .hljs-operator,
.cafe-code .hljs-variable,
.cafe-code .hljs-selector-attr,
.cafe-code .hljs-selector-class,
.cafe-code .hljs-selector-id {
  color: #005cc5;
}
.cafe-code .hljs-regexp,
.cafe-code .hljs-string,
.cafe-code .hljs-meta .hljs-string {
  color: #032f62;
}
.cafe-code .hljs-built_in,
.cafe-code .hljs-symbol {
  color: #e36209;
}
.cafe-code .hljs-comment,
.cafe-code .hljs-code,
.cafe-code .hljs-formula {
  color: #6a737d;
}
.cafe-code .hljs-name,
.cafe-code .hljs-quote,
.cafe-code .hljs-selector-tag,
.cafe-code .hljs-selector-pseudo {
  color: #22863a;
}
.cafe-code .hljs-subst {
  color: #24292e;
}
.cafe-code .hljs-section {
  color: #005cc5;
  font-weight: bold;
}
.cafe-code .hljs-bullet {
  color: #735c0f;
}
.cafe-code .hljs-emphasis {
  color: #24292e;
  font-style: italic;
}
.cafe-code .hljs-strong {
  color: #24292e;
  font-weight: 700;
}
.cafe-code .hljs-addition {
  color: #22863a;
  background-color: #f0fff4;
}
.cafe-code .hljs-deletion {
  color: #b31d28;
  background-color: #ffeef0;
}

/* ---- Editor and chat page shells ---- */
.cafe-island-main {
  min-height: 0;
}
/* The editor's phone header takes its height from this, as in the old app's shell. */
#cafe-write-root,
#cafe-chat-root {
  --mobile-header-height: 52px;
}
/* The header keeps its height; the scroll area takes what is left. */
#cafe-write-root > header,
#cafe-chat-root > header {
  flex-shrink: 0;
}
#cafe-write-root > :not(header),
#cafe-chat-root > :not(header) {
  flex: 0 0 auto;
}
/* Only the editor's scroll area (the one with h-full) fills the height. The
   other children (the file input, the dialog and toast holders) must not
   take a share of it. */
#cafe-write-root > .h-full {
  flex: 1 1 0;
  min-height: 0;
}

/* The stand-in for the editor and chat until their script starts; the phone layout differs. */
@media (max-width: 767px) {
  .cafe-skeleton-page {
    display: none !important;
  }
}

/* ---- Login and Signup ---- */
.cafe-auth-input:focus {
  border-color: #999 !important;
  background: #fff !important;
  box-shadow: 0 0 1px rgba(0, 0, 0, 0.2), 0 1px 3px rgba(0, 0, 0, 0.14);
}
.cafe-auth-input::placeholder,
.cafe-otp::placeholder {
  color: var(--cafe-ink-5);
  opacity: 1;
}
.cafe-otp:focus {
  border-color: #999 !important;
  box-shadow: 0 0 0 2px #077ddf;
}
.cafe-auth-btn-solid:hover:not(:disabled) {
  background: #383838 !important;
}
.cafe-auth-btn-outline:hover:not(:disabled) {
  background: #f8f8f8 !important;
}
.cafe-auth-btn-solid:disabled,
.cafe-auth-btn-outline:disabled {
  cursor: default !important;
}
.cafe-auth-link-btn {
  padding: 0;
  border: 0;
  background: none;
  color: var(--cafe-ink);
  font: inherit;
  font-weight: 500;
  letter-spacing: inherit;
  text-decoration: underline;
  cursor: pointer;
}

/* ---- Home feed ---- */
.cafe-feed > * + * {
  border-top: 1px solid var(--cafe-outline);
}
@media (max-width: 767px) {
  .cafe-island-main {
    flex-grow: 0 !important;
    height: calc(100vh - 57px) !important;
  }
  html[data-cafe-sidebar='open'] .cafe-np,
  .cafe-np {
    left: 0;
    width: 100%;
    max-width: none;
    border-right: 0;
    box-shadow: none;
  }
  .cafe-container-home {
    padding: 16px !important;
  }
  .cafe-home-bar {
    display: flex !important;
  }
}

/* ---- Pop-up menu (CAFE.popupMenu) ---- */
.cafe-popup {
  position: fixed;
  z-index: 70;
  min-width: 160px;
  padding: 4px;
  border-radius: 8px;
  background: #fff;
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.08), 0 8px 24px rgba(0, 0, 0, 0.12);
  font-family: 'InterVar', ui-sans-serif, system-ui, sans-serif;
  font-size: 14px;
  font-weight: 420;
  letter-spacing: 0.02em;
  color: #171717;
}
.cafe-popup-item {
  display: flex;
  width: 100%;
  height: 28px;
  align-items: center;
  gap: 8px;
  padding: 0 8px;
  border: 0;
  border-radius: 6px;
  background: none;
  font: inherit;
  text-align: left;
  cursor: pointer;
}
.cafe-popup-item:hover {
  background: var(--cafe-surface-2);
}
.cafe-popup-item.danger {
  color: #b41d1d;
}
.cafe-popup-icon {
  display: inline-flex;
  color: #7c7c7c;
}
.cafe-popup-item.danger .cafe-popup-icon {
  color: inherit;
}
